const createInfiniteParams = <
  K extends Pick<QueryKey<Options>[0], "body" | "headers" | "path" | "query">,
>(
  queryKey: QueryKey<Options>,
  page: K,
) => {
  const params = { ...queryKey[0] };
  if (page.body) {
    params.body = {
      ...(queryKey[0].body as any),
      ...(page.body as any),
    };
  }
  if (page.headers) {
    params.headers = {
      ...queryKey[0].headers,
      ...page.headers,
    };
  }
  if (page.path) {
    params.path = {
      ...(queryKey[0].path as any),
      ...(page.path as any),
    };
  }
  if (page.query) {
    params.query = {
      ...(queryKey[0].query as any),
      ...(page.query as any),
    };
  }
  return params as unknown as typeof page;
};

export const getFeatureFlagsInfiniteQueryKey = (
  options: Options<GetFeatureFlagsData>,
): QueryKey<Options<GetFeatureFlagsData>> =>
  createQueryKey("getFeatureFlags", options, true);

export const getFeatureFlagsInfiniteOptions = (
  options: Options<GetFeatureFlagsData>,
) =>
  infiniteQueryOptions<
    GetFeatureFlagsResponse,
    AxiosError<DefaultError>,
    InfiniteData<GetFeatureFlagsResponse>,
    QueryKey<Options<GetFeatureFlagsData>>,
    | number
    | Pick<
        QueryKey<Options<GetFeatureFlagsData>>[0],
        "body" | "headers" | "path" | "query"
      >
  >(
    // @ts-ignore
    {
      queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<
          QueryKey<Options<GetFeatureFlagsData>>[0],
          "body" | "headers" | "path" | "query"
        > =
          typeof pageParam === "object"
            ? pageParam
            : {
                query: {
                  page: pageParam,
                },
              };
        const params = createInfiniteParams(queryKey, page);
        const { data } = await FeatureFlagAdminController.getFeatureFlags({
          ...options,
          ...params,
          signal,
          throwOnError: true,
        });
        return data;
      },
      queryKey: getFeatureFlagsInfiniteQueryKey(options),
    },
  );

